//! Output parity between `boostr_audio::narration` and the JavaScript
//! narration-script modules it ports.
//!
//! The fixture (`tests/fixtures/narration_oracle.json`) is checked in and
//! was generated by `tests/tools/narration_oracle/narration_oracle.mjs` over
//! the corpus beside it. Each case holds a function name, its input, and
//! the JavaScript output: a value, or `{ "error": message }`. The speech
//! check's outputs write every number as JavaScript's `String(x)`, which
//! reads back as the exact double, so they compare exactly.
//!
//! The glitch fixture (`tests/fixtures/narration_glitch_oracle.json`) was
//! generated by `tests/tools/narration_oracle/glitch_oracle.mjs` over the
//! signals in `signals.mjs` beside it, which `common::signals` builds bit
//! for bit. Each case holds the FNV-1a hash of its input, the hashes of the
//! repaired samples, and every number as `String(x)`: all compare exactly.

use std::path::Path;
use std::process::Command;

use boostr_audio::Error;
use boostr_audio::narration::{self, ChunkOptions, HeardWord, PAUSES, STRAY_PAUSE};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};

mod common;
use common::load_json;
use common::signals::{self, Run, VoiceMedian};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/narration_oracle.mjs"
);
const GLITCH_FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_glitch_oracle.json"
);
const GLITCH_ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/glitch_oracle.mjs"
);

/// The JavaScript error message carries its command name before the text
/// the library reports.
const WRITTEN_PREFIX: &str = "speak --written: ";

#[derive(Debug, Deserialize)]
struct Fixture {
    pauses: Value,
    #[serde(rename = "strayPause")]
    stray_pause: f64,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    #[serde(rename = "fn")]
    function: String,
    input: Value,
    output: Value,
}

fn reason(e: Error) -> String {
    match e {
        Error::InvalidArgument { reason, .. }
        | Error::DataError { reason }
        | Error::ModelError { reason } => reason,
        other => other.to_string(),
    }
}

fn to_json<T: Serialize>(r: boostr_audio::Result<T>) -> Value {
    match r {
        Ok(v) => serde_json::to_value(v).unwrap_or_else(|e| panic!("serializing output: {e}")),
        Err(e) => json!({ "error": reason(e) }),
    }
}

fn text<'a>(v: &'a Value, what: &str) -> &'a str {
    v.as_str()
        .unwrap_or_else(|| panic!("fixture {what} is not a string: {v}"))
}

fn heard(input: &Value) -> Vec<HeardWord> {
    serde_json::from_value(input["heard"].clone())
        .unwrap_or_else(|e| panic!("fixture heard words: {e}: {input}"))
}

/// Functions whose fixture outputs write numbers as strings.
fn is_exact(function: &str) -> bool {
    matches!(function, "checkSpeech" | "alignScript" | "strayPauses")
}

/// The port's output for one case, shaped as the oracle writes it.
fn actual(case: &Case) -> Value {
    let input = &case.input;
    match case.function.as_str() {
        "phrases" => to_json(narration::phrases(text(input, "script"))),
        "chunks" => {
            let o = &input["options"];
            let options = ChunkOptions {
                lines: o["lines"]
                    .as_bool()
                    .unwrap_or_else(|| panic!("options.lines: {o}")),
                max: o["max"]
                    .as_u64()
                    .unwrap_or_else(|| panic!("options.max: {o}")) as usize,
                whole: o["whole"]
                    .as_bool()
                    .unwrap_or_else(|| panic!("options.whole: {o}")),
            };
            to_json(narration::chunks(text(&input["script"], "script"), options))
        }
        "withoutTags" => to_json(narration::without_tags(text(input, "text"))),
        "say" => to_json(narration::say(text(input, "text"))),
        "shown" => to_json(narration::shown(text(input, "text"))),
        "spoken" => to_json(narration::spoken(text(input, "text"))),
        "sayable" => to_json(narration::sayable(text(input, "text"))),
        "writtenScript" => {
            let ear = text(&input["ear"], "ear");
            let written = text(&input["written"], "written");
            let run = || -> boostr_audio::Result<Value> {
                let w = narration::written_script(ear, written)?;
                let spans = w.spans(&narration::phrases(ear)?)?;
                Ok(json!({ "text": w.text, "spans": spans }))
            };
            match run() {
                Ok(v) => v,
                Err(e) => json!({ "error": format!("{WRITTEN_PREFIX}{}", reason(e)) }),
            }
        }
        "parseSubtitles" => to_json(narration::parse_subtitles(text(input, "text"))),
        "parseTimedScript" => to_json(narration::parse_timed_script(text(input, "text"))),
        "readScript" => to_json(narration::script_source(
            text(&input["file"], "file"),
            text(&input["raw"], "raw"),
        )),
        "spokenNumbers" => to_json(narration::spoken_numbers(text(input, "text"))),
        "writtenNumbers" => to_json(narration::written_numbers(text(input, "text"))),
        "numbersIn" => to_json(narration::numbers_in(text(input, "text"))),
        "isNumberWord" => to_json(narration::is_number_word(text(input, "word"))),
        "checkSpeech" => to_json(narration::check_speech(
            &heard(input),
            text(&input["text"], "text"),
        )),
        "alignScript" => to_json(narration::align_script(
            &heard(input),
            text(&input["text"], "text"),
        )),
        "strayPauses" => to_json(narration::stray_pauses(
            &heard(input),
            text(&input["text"], "text"),
        )),
        other => panic!("fixture names an unknown function {other:?}"),
    }
}

/// JSON equality with numbers compared as f64: JavaScript writes `0` where
/// serde writes `0.0`.
fn same(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64() == y.as_f64(),
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(x, y)| same(x, y))
        }
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| same(v, w)))
        }
        _ => a == b,
    }
}

/// [`same`], but `want` writes each number as `String(x)`: a number in
/// `got` must equal that text read back, exactly. NaN equals NaN.
fn same_exact(got: &Value, want: &Value) -> bool {
    match (got, want) {
        (Value::Number(x), Value::String(y)) => match (x.as_f64(), y.parse::<f64>()) {
            (Some(x), Ok(y)) => x == y || (x.is_nan() && y.is_nan()),
            _ => false,
        },
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(x, y)| same_exact(x, y))
        }
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len()
                && x.iter()
                    .all(|(k, v)| y.get(k).is_some_and(|w| same_exact(v, w)))
        }
        _ => got == want,
    }
}

#[test]
fn matches_javascript_on_every_case() {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");
    let pauses = serde_json::to_value(PAUSES).unwrap_or_else(|e| panic!("serializing PAUSES: {e}"));
    assert!(
        same(&pauses, &fixture.pauses),
        "PAUSES: got {pauses}, want {}",
        fixture.pauses
    );
    assert_eq!(STRAY_PAUSE, fixture.stray_pause, "STRAY_PAUSE");

    let failures: Vec<(&Case, Value)> = fixture
        .cases
        .iter()
        .map(|case| (case, actual(case)))
        .filter(|(case, got)| {
            if is_exact(&case.function) {
                !same_exact(got, &case.output)
            } else {
                !same(got, &case.output)
            }
        })
        .collect();
    if let Some((case, got)) = failures.first() {
        panic!(
            "{} of {} cases differ. First: {}\ninput:    {}\nexpected: {}\nactual:   {}",
            failures.len(),
            fixture.cases.len(),
            case.function,
            case.input,
            case.output,
            got
        );
    }
}

/// Reruns `oracle` and checks the committed `fixture` is what it prints.
/// Needs `NARRATION_JS_DIR` (the directory holding the JavaScript modules)
/// and `node` on PATH.
fn assert_oracle_current(oracle: &str, fixture: &str) {
    let Some(js_dir) = std::env::var_os("NARRATION_JS_DIR").filter(|d| !d.is_empty()) else {
        eprintln!("skipping: narration oracle rerun unavailable; set NARRATION_JS_DIR");
        return;
    };
    let Ok(output) = Command::new("node")
        .arg(oracle)
        .env("NARRATION_JS_DIR", &js_dir)
        .output()
    else {
        eprintln!("skipping: narration oracle rerun unavailable; put node on PATH");
        return;
    };
    assert!(
        output.status.success(),
        "{oracle} failed ({}): {}",
        output.status,
        String::from_utf8_lossy(&output.stderr)
    );
    let fresh: Value = serde_json::from_slice(&output.stdout)
        .unwrap_or_else(|e| panic!("parsing {oracle} output: {e}"));
    let committed: Value = load_json(Path::new(fixture));
    assert!(
        fresh == committed,
        "{fixture} is stale: regenerate it with `NARRATION_JS_DIR=<dir> node {oracle} > {fixture}`"
    );
}

#[test]
fn oracle_fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}

#[test]
fn glitch_oracle_fixture_is_current() {
    assert_oracle_current(GLITCH_ORACLE, GLITCH_FIXTURE);
}

#[derive(Debug, Deserialize)]
struct GlitchFixture {
    heated: String,
    cases: Vec<GlitchCase>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct GlitchCase {
    name: String,
    rate: u32,
    n: usize,
    input: String,
    tidy: Option<TidyOut>,
    clicks: Option<Vec<String>>,
    repair_clicks: Option<RepairOut>,
    pitches: Option<Vec<String>>,
    median_pitch: Option<String>,
    heat: Option<Vec<HeatOut>>,
}

#[derive(Debug, Deserialize)]
struct TidyOut {
    samples: String,
    faults: Vec<String>,
    repairs: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct RepairOut {
    samples: String,
    fixed: Vec<String>,
    left: Vec<String>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct HeatOut {
    voice_median: Option<String>,
    heat: String,
}

/// `String(x)` read back: the exact double.
fn num(text: &str) -> f64 {
    text.parse()
        .unwrap_or_else(|e| panic!("fixture number {text:?}: {e}"))
}

fn nums(texts: &[String]) -> Vec<f64> {
    texts.iter().map(|t| num(t)).collect()
}

/// Every difference between the port and the fixture on one case.
fn glitch_differences(case: &signals::Case, want: &GlitchCase) -> Vec<String> {
    let mut diffs = Vec::new();
    let mut check = |what: &str, got: String, expected: String| {
        if got != expected {
            diffs.push(format!("{what}: got {got}, want {expected}"));
        }
    };
    let x = signals::render(case.n, &case.ops);
    let input = signals::fnv1a(&x);
    if input != want.input {
        return vec![format!(
            "input signal differs from the oracle's: hash {input}, want {}",
            want.input
        )];
    }
    match &case.run {
        Run::Edges => {
            let (Some(t), Some(c), Some(r)) = (&want.tidy, &want.clicks, &want.repair_clicks)
            else {
                return vec!["fixture lacks tidy, clicks or repairClicks".to_string()];
            };
            let got = narration::tidy(&x, case.rate);
            check(
                "tidy samples",
                signals::fnv1a(&got.samples),
                t.samples.clone(),
            );
            check(
                "tidy faults",
                format!("{:?}", got.faults),
                format!("{:?}", t.faults),
            );
            check(
                "tidy repairs",
                format!("{:?}", got.repairs),
                format!("{:?}", t.repairs),
            );
            let found = narration::clicks(&x, case.rate);
            check("clicks", format!("{found:?}"), format!("{:?}", nums(c)));
            let got = narration::repair_clicks(&x, case.rate);
            check(
                "repairClicks samples",
                signals::fnv1a(&got.samples),
                r.samples.clone(),
            );
            check(
                "repairClicks fixed",
                format!("{:?}", got.fixed),
                format!("{:?}", nums(&r.fixed)),
            );
            check(
                "repairClicks left",
                format!("{:?}", got.left),
                format!("{:?}", nums(&r.left)),
            );
        }
        Run::Pitch(medians) => {
            let (Some(p), Some(m), Some(h)) = (&want.pitches, &want.median_pitch, &want.heat)
            else {
                return vec!["fixture lacks pitches, medianPitch or heat".to_string()];
            };
            check(
                "pitches",
                format!("{:?}", narration::pitches(&x)),
                format!("{:?}", nums(p)),
            );
            let own = narration::median_pitch(&x);
            check("medianPitch", format!("{own:?}"), format!("{:?}", num(m)));
            if medians.len() != h.len() {
                return vec![format!(
                    "{} heat readings, fixture has {}",
                    medians.len(),
                    h.len()
                )];
            }
            for (median, want) in medians.iter().zip(h) {
                // JavaScript's absent median is `undefined`; NaN reads as falsy
                // the same way.
                let voice = match median {
                    VoiceMedian::Absent => f64::NAN,
                    VoiceMedian::Hz(hz) => *hz,
                    VoiceMedian::Own => own,
                };
                let given = (!voice.is_nan()).then(|| format!("{voice:?}"));
                let fixture = want
                    .voice_median
                    .as_deref()
                    .map(|v| format!("{:?}", num(v)));
                check(
                    "heat voice median",
                    format!("{given:?}"),
                    format!("{fixture:?}"),
                );
                check(
                    format!("heat at {given:?}").as_str(),
                    format!("{:?}", narration::heat(&x, voice)),
                    format!("{:?}", num(&want.heat)),
                );
            }
        }
    }
    diffs
}

#[test]
fn glitch_checks_match_javascript_on_every_signal() {
    let fixture: GlitchFixture = load_json(Path::new(GLITCH_FIXTURE));
    assert_eq!(narration::HEATED, num(&fixture.heated), "HEATED");
    let cases = signals::cases();
    let ours: Vec<(&str, u32, usize)> = cases.iter().map(|c| (c.name, c.rate, c.n)).collect();
    let theirs: Vec<(&str, u32, usize)> = fixture
        .cases
        .iter()
        .map(|c| (c.name.as_str(), c.rate, c.n))
        .collect();
    assert_eq!(
        ours, theirs,
        "common::signals and signals.mjs list different cases"
    );
    let failures: Vec<String> = cases
        .iter()
        .zip(&fixture.cases)
        .flat_map(|(case, want)| {
            glitch_differences(case, want)
                .into_iter()
                .map(move |d| format!("{}: {d}", case.name))
        })
        .collect();
    assert!(
        failures.is_empty(),
        "{} differences over {} signals:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}
